def test_owner_mismatch_raises_permission_error():
    store = {}
    task = {"owner": "alice", "version": "1", "job_text": "task1", "criteria_version": "1"}
    profile = {"owner": "bob", "version": "1"}
    compute_called = [False]

    def compute():
        compute_called[0] = True
        return 42

    try:
        evaluate(store, task, profile, compute)
        assert False, "Expected PermissionError"
    except PermissionError:
        pass

    # compute must NOT have been called
    assert compute_called[0] is False, "compute should not be called on owner mismatch"
    # store must NOT have been modified
    assert store == {}, "store should be unchanged after PermissionError"


def test_task_version_mismatch_returns_none_no_side_effects():
    store = {"key": "value"}
    task = {"owner": "alice", "version": "2", "job_text": "task1", "criteria_version": "1"}
    profile = {"owner": "alice", "version": "1"}

    result = evaluate(store, task, profile, lambda: 99)

    assert result is None, f"Expected None, got {result}"
    # store must be unchanged
    assert store == {"key": "value"}, "store should be unchanged when versions mismatch"


def test_cached_result_reuses_on_unchanged_input():
    store = {}
    task = {"owner": "alice", "version": "1", "job_text": "task1", "criteria_version": "1"}
    profile = {"owner": "alice", "version": "1"}

    def compute():
        return "computed_value"

    result1 = evaluate(store, task, profile, compute)
    result2 = evaluate(store, task, profile, compute)

    assert result1 == result2 == "computed_value"
    # compute called only once
    assert store == {("alice", "1", "1", "task1"): "computed_value"}


def test_cache_key_includes_all_fields():
    store = {}
    task1 = {"owner": "alice", "version": "1", "job_text": "task1", "criteria_version": "1"}
    profile1 = {"owner": "alice", "version": "1"}
    task2 = {"owner": "alice", "version": "1", "job_text": "task1", "criteria_version": "2"}
    profile2 = {"owner": "alice", "version": "1"}

    evaluate(store, task1, profile1, lambda: "val1")
    evaluate(store, task2, profile2, lambda: "val2")

    # Different criteria_version should produce different keys
    assert len(store) == 2, f"Expected 2 entries, got {len(store)}"
    keys = list(store.keys())
    assert keys[0] != keys[1]


def test_unused_zero_and_none_values_are_reused():
    store = {}
    task = {"owner": "alice", "version": "1", "job_text": "", "criteria_version": None}
    profile = {"owner": "alice", "version": "1"}

    def compute():
        return 0

    result1 = evaluate(store, task, profile, compute)
    result2 = evaluate(store, task, profile, compute)

    assert result1 == result2 == 0
    # key with 0/None should be reused
    assert len(store) == 1
    key = list(store.keys())[0]
    assert key == ("alice", "1", None, "")


def test_compute_exception_propagates_and_not_cached():
    store = {}
    task = {"owner": "alice", "version": "1", "job_text": "task1", "criteria_version": "1"}
    profile = {"owner": "alice", "version": "1"}

    def compute():
        raise RuntimeError("compute failed")

    try:
        evaluate(store, task, profile, compute)
        assert False, "Expected RuntimeError"
    except RuntimeError:
        pass

    # store must NOT contain the failed key
    assert "task1" not in str(store) or len(store) == 0, "store should not contain failed computation"


